const platform = $('Determine TikTok Sync Period').first().json;
const periodStart = new Date(platform.metrics_period_start).getTime();
const periodEnd = new Date(platform.period_end).getTime();
const numberOrZero = value => {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.trunc(parsed) : 0;
};
const toIsoDate = video => {
  const raw = video.createTimeISO ?? video.createTime;
  if (typeof raw === 'number') return new Date(raw * 1000).toISOString();
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
};
const rawItems = items.map(item => item.json);
const failures = rawItems.filter(item => item?.error || item?.errorCode || item?.errorDescription || item?.requestErrorMessages);
const videos = [];
for (const video of rawItems) {
  const videoId = video.id ?? video.videoId;
  const videoUrl = video.webVideoUrl ?? video.videoUrl;
  const publishedAt = toIsoDate(video);
  if (!videoId || !videoUrl || !publishedAt) continue;
  const publishedTime = new Date(publishedAt).getTime();
  if (publishedTime < periodStart || publishedTime >= periodEnd) continue;
  videos.push({
    video_id: String(videoId),
    video_url: String(videoUrl),
    description: String(video.text ?? video.description ?? '').trim() || null,
    published_at: publishedAt,
    play_count: numberOrZero(video.playCount),
    digg_count: numberOrZero(video.diggCount),
    comment_count: numberOrZero(video.commentCount),
    share_count: numberOrZero(video.shareCount),
    raw_data: {
      author: video.authorMeta?.name ?? null,
      hashtags: Array.isArray(video.hashtags) ? video.hashtags : [],
      collect_count: numberOrZero(video.collectCount),
      is_pinned: Boolean(video.isPinned)
    }
  });
}
return [{ json: {
  ...platform,
  fetch_succeeded: videos.length > 0 || failures.length === 0,
  has_videos: videos.length > 0,
  videos
} }];

const platform =
  $('Continue TikTok Platform').first().json;

const comments = items
  .filter(item =>
    item.json.id &&
    item.json.comment_text
  )
  .map(item => ({
    // رقم السجل داخل جدول tiktok_comments
    source_record_id: item.json.id,

    // معرف التعليق الأصلي في TikTok
    tiktok_comment_id:
      item.json.tiktok_comment_id,

    video_id:
      item.json.video_id || null,

    // اسم العمود في الجدول commenter_username
    author_username:
      item.json.commenter_username || null,

    video_url:
      item.json.video_url || null,

    comment_text:
      item.json.comment_text,

    // اسم العمود في الجدول comment_date
    posted_at:
      item.json.comment_date || null,

    // الجدول يحتوي like_count كعمود منفصل
    public_metrics: {
      like_count: Number(
        item.json.like_count || 0
      )
    }
  }));

if (!comments.length) {
  return [];
}

return [
  {
    json: {
      client_id: platform.client_id,
      branch_id:
        platform.branch_id ?? null,
      platform_id:
        platform.platform_id,

      platform_name: 'tiktok',
      source_table: 'tiktok_comments',

      comments
    }
  }
];

const batch = $('Create TikTok AI Batch').item.json;

let text =
  $json.text ||
  $json.output?.[0]?.content?.[0]?.text ||
  $json.message?.content ||
  $json.content?.find(item => item.type === 'output_text')?.text ||
  '';

text = String(text)
  .replace(/^\uFEFF/, '')
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

if (!text) {
  throw new Error('لم يتم العثور على نتيجة تحليل تعليقات TikTok');
}

const tryParse = value => {
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
};

const normalizeJson = value => value
  .replace(/,\s*([}\]])/g, '$1')
  .trim();

let parsed = tryParse(text);

if (!parsed) {
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    parsed = tryParse(normalizeJson(text.slice(firstBrace, lastBrace + 1)));
  }
}

// إذا كانت الاستجابة مقطوعة، استخرج كائنات النتائج المكتملة فقط.
if (!parsed) {
  const resultsKey = text.search(/"results"\s*:/i);
  const arrayStart = resultsKey === -1 ? -1 : text.indexOf('[', resultsKey);
  const recovered = [];

  if (arrayStart !== -1) {
    let depth = 0;
    let start = -1;
    let inString = false;
    let escaped = false;

    for (let i = arrayStart + 1; i < text.length; i++) {
      const char = text[i];

      if (inString) {
        if (escaped) escaped = false;
        else if (char === '\\') escaped = true;
        else if (char === '"') inString = false;
        continue;
      }

      if (char === '"') {
        inString = true;
        continue;
      }

      if (char === '{') {
        if (depth === 0) start = i;
        depth++;
      } else if (char === '}') {
        depth--;
        if (depth === 0 && start !== -1) {
          const result = tryParse(normalizeJson(text.slice(start, i + 1)));
          if (result) recovered.push(result);
          start = -1;
        }
      }
    }
  }

  if (recovered.length > 0) {
    parsed = { results: recovered };
    console.log('تم استرداد ' + recovered.length + ' نتيجة مكتملة من استجابة TikTok غير مكتملة');
  }
}

if (!parsed || !Array.isArray(parsed.results)) {
  throw new Error('تعذر استخراج نتائج TikTok من استجابة الذكاء الاصطناعي');
}

const comments = Array.isArray(batch.comments) ? batch.comments : [];
const commentMap = new Map(
  comments.map(comment => [String(comment.source_record_id), comment])
);

const expectedIds = new Set(
  comments.map(comment => String(comment.source_record_id))
);

const returnedIds = new Set(
  parsed.results
    .map(result => result.source_record_id ?? result.id)
    .filter(id => id !== undefined && id !== null)
    .map(id => String(id))
);

const missingIds = [...expectedIds].filter(id => !returnedIds.has(id));
if (missingIds.length > 0) {
  console.log('ستبقى تعليقات TikTok الناقصة معلقة لإعادة التحليل: ' + missingIds.join(', '));
}

const toBoolean = value => value === true || value === 'true';
const allowedSentiments = ['positive', 'negative', 'neutral'];
const allowedSeverities = ['low', 'medium', 'high'];
const output = [];

for (const result of parsed.results) {
  const sourceRecordId = result.source_record_id ?? result.id;

  if (sourceRecordId === undefined || sourceRecordId === null) {
    console.log('تم تجاهل نتيجة لا تحتوي على source_record_id');
    continue;
  }

  const originalComment = commentMap.get(String(sourceRecordId));
  if (!originalComment) {
    console.log('تم تجاهل معرف غير موجود في الدفعة: ' + sourceRecordId);
    continue;
  }

  const sentiment = allowedSentiments.includes(result.sentiment)
    ? result.sentiment
    : 'neutral';
  const severity = allowedSeverities.includes(result.severity)
    ? result.severity
    : 'low';
  const category = Array.isArray(result.category)
    ? result.category
    : [result.category || 'أخرى'];

  output.push({
    json: {
      client_id: batch.client_id,
      branch_id: batch.branch_id ?? null,
      platform_id: batch.platform_id,
      platform_name: 'tiktok',
      source_table: 'tiktok_comments',
      source_record_id: Number(sourceRecordId),
      external_id: originalComment.tiktok_comment_id || null,
      sentiment,
      category,
      severity,
      needs_reply: toBoolean(result.needs_reply),
      is_sales_opportunity: toBoolean(result.is_sales_opportunity),
      is_complaint: toBoolean(result.is_complaint),
      suggested_reply: result.suggested_reply || null,
      reason: result.reason || null,
      analysis_summary: result.analysis_summary || null,
      analysis_status: 'completed',
      model_name: 'gpt-4o-mini',
      analyzed_at: new Date().toISOString()
    }
  });
}

if (output.length === 0) {
  throw new Error('لم تُسترد أي نتيجة صالحة من دفعة TikTok');
}

return output;

const platform =
  $('Determine TikTok Sync Period').first().json;

return [
  {
    json: {
      client_id: platform.client_id,
      branch_id: platform.branch_id ?? null,
      platform_id: platform.id,
      platform_name: 'tiktok'
    }
  }
