const platform = $('Normalize TikTok Videos').first().json;
const rows = items.flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
const existingCounts = new Map(rows.filter(row => row?.video_id).map(row => [String(row.video_id), Number(row.comment_count || 0)]));
const now = new Date().toISOString();
const videos = platform.videos ?? [];
const videoRows = videos.map(video => ({
  client_id: platform.client_id,
  branch_id: platform.branch_id ?? null,
  platform_id: platform.id,
  video_id: video.video_id,
  video_url: video.video_url,
  description: video.description,
  published_at: video.published_at,
  play_count: video.play_count,
  digg_count: video.digg_count,
  comment_count: video.comment_count,
  share_count: video.share_count,
  last_scraped_at: now,
  raw_data: video.raw_data,
  updated_at: now
}));
const commentTargets = videos.filter(video => {
  const oldCount = existingCounts.get(String(video.video_id));
  return video.comment_count > 0 && (oldCount === undefined || video.comment_count > oldCount);
});
return [{ json: {
  ...platform,
  video_rows: videoRows,
  comment_target_urls: commentTargets.map(video => video.video_url),
  comment_target_videos: commentTargets
} }];

const platform = $('Prepare TikTok Video Sync').first().json;
const periodStart = new Date(platform.period_start).getTime();
const periodEnd = new Date(platform.period_end).getTime();
const monitoredUsername = String(platform.tiktok_username || '').replace(/^@/, '').trim().toLowerCase();
const videos = platform.comment_target_videos ?? [];
const videoByUrl = new Map(videos.map(video => [String(video.video_url).split('?')[0], video]));
const output = [];
const rawItems = items.map(item => item.json);
const failures = rawItems.filter(item => item?.error || item?.errorCode || item?.errorDescription || item?.requestErrorMessages);
for (const comment of rawItems) {
  const commentId = comment.cid ?? comment.commentId ?? comment.id;
  const text = String(comment.text ?? '').trim();
  if (!commentId || !text) continue;
  const rawDate = comment.createTimeISO ?? comment.createTime;
  const commentDate = typeof rawDate === 'number' ? new Date(rawDate * 1000) : new Date(rawDate);
  const commentTime = commentDate.getTime();
  if (Number.isNaN(commentTime) || commentTime < periodStart || commentTime >= periodEnd) continue;
  const authorUsername = String(comment.uniqueId ?? comment.username ?? '').replace(/^@/, '').trim();
  if (monitoredUsername && authorUsername.toLowerCase() === monitoredUsername) continue;
  const videoUrl = String(comment.videoWebUrl ?? comment.videoUrl ?? '').trim();
  const video = videoByUrl.get(videoUrl.split('?')[0]);
  const urlVideoId = videoUrl.split('/video/')[1]?.split('?')[0]?.split('/')[0] ?? null;
  const replyToId = comment.repliesToId ?? comment.replyToCommentId ?? null;
  output.push({ json: {
    fetch_succeeded: true,
    has_comments: true,
    client_id: platform.client_id,
    branch_id: platform.branch_id ?? null,
    platform_id: platform.id,
    tiktok_comment_id: String(commentId),
    video_id: String(comment.aweme_id ?? comment.videoId ?? video?.video_id ?? urlVideoId ?? '') || null,
    comment_text: text,
    author_username: authorUsername || null,
    author_name: comment.nickname ?? null,
    author_avatar_url: comment.avatarThumbnail ?? null,
    video_url: videoUrl || video?.video_url || null,
    video_description: video?.description ?? null,
    posted_at: commentDate.toISOString(),
    public_metrics: {
      like_count: Number(comment.diggCount ?? comment.likes ?? 0) || 0,
      reply_count: Number(comment.replyCommentTotal ?? comment.replies ?? 0) || 0
    },
    is_reply: Boolean(replyToId),
    reply_to_comment_id: replyToId ? String(replyToId) : null,
    analysis_status: 'pending',
    raw_data: { comment, monitored_username: platform.tiktok_username || null, client_platform_id: platform.id }
  } });
}
if (output.length === 0) {
  return [{ json: {
    fetch_succeeded: failures.length === 0,
    has_comments: false,
    client_id: platform.client_id,
    branch_id: platform.branch_id ?? null,
    platform_id: platform.id,
    message: failures.length ? 'تعذر جلب تعليقات TikTok من Clockworks' : 'لا توجد تعليقات TikTok جديدة داخل الفترة المحددة'
  } }];
}
return output;
